 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-088",
   "status_as_recorded": "supported",
   "finding": "Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence. Unmatched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08. Usage-matched vs role: paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96. Vs terminal: +0.0777 t=2.37 p=0.0261 n=25."
  },
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "Having a similar-profile teammate does not separate absorption from cascade when a player sits. mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed)."
  },
  {
   "id": "FAM:SF36",
   "status_as_recorded": "supported",
   "finding": "A point of opponent three-point luck moves second-half possession share less than a point of opponent two-point luck or expected net points."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Describes how play-type mix shifts by halftime margin, crunch time and after runs. OTHER +2.26 to +2.48pp in H2 in every bucket; crunch OTHER +6.08pp, PULL_UP +1.20pp at -0.045 PPP; post-run DRIVE +3.75pp, OTHER -6.72pp."
  },
  {
   "id": "FAM:SF-APPS-073",
   "status_as_recorded": "artifact",
   "finding": "Running play type X raises the same team's next 1-5 possession PPP vs a matched baseline (action memory). Global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise."
  },
  {
   "id": "FAM:SF20",
   "status_as_recorded": "untestable",
   "finding": "Real player absences move the association structure (V1 confirmed), but LOO simulation did not predict the magnitude (V2 failed). V1(a) 16/23 above p95 binomial p=2.67e-16; V1(b) +0.142 CI[+0.103,+0.187] CONFIRMED; V2a rho=+0.288 p=0.077 CI[-0.244,+0.667]; V2b rho=+0.253 p=0.115 NOT."
  },
  {
   "id": "FAM:SF-APPS-025",
   "status_as_recorded": "untestable",
   "finding": "Teams that abandon a suppressed play type show a smaller matched-pair overall six-PT H1->H2 excess decline than teams that continue. Group B caliper-0.10 CI includes 0 (p=0.386, n=255 clusters=242); Group B is a reconstructed post-hoc cohort, not a validated successful-adaptation sample."
  },
  {
   "id": "FAM:SF-CHT-063",
   "status_as_recorded": "artifact",
   "finding": "The BEST-vs-continue gap after a slump is evidence of costly failure to abandon a suppressed play (depends on the slump event). Gap is the same without a slump (+0.239) and with a fixed CUT-heavy ranking (+0.238)."
  },
  {
   "id": "FAM:SF-APPS-015",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Teams and players differ in how often H2 trigger possessions land on the engine's BEST vs AVOID counter. Team AVOID% ranges 50.6% (ORL) to 6.8% (SAC); team BEST% 0.0%-15.8%."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-052",
   "what_failed": "Using similar-profile teammates to distinguish absorption from cascade when a player sits.",
   "why": "Similarity does not separate absorption from cascade; almost always findable. LABEL_ERROR."
  },
  {
   "id": "FAM:SF-APPS-073",
   "what_failed": "Measuring persistent impact score lag curves globally without team-season demeaning.",
   "why": "Apparent effect produced by a construction, selection or labelling flaw; global lifts disappear after team-season demeaning."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferring defensive scheme changes from play-by-play data.",
   "why": "Question not answerable with the data or design; inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise. LABEL_ERROR."
  },
  {
   "id": "FAM:SF20",
   "what_failed": "LOO simulation predicting the magnitude of structure movement under real player absences.",
   "why": "V2 (prediction of magnitude) failed. LIM:small_sample."
  },
  {
   "id": "FAM:SF-APPS-025",
   "what_failed": "Comparing 'adapt' vs 'continue' teams based on post-hoc cohort reconstruction to assess overall offense excess decline.",
   "why": "Question not answerable with the data or design; Group B CI includes 0; Group B is a reconstructed post-hoc cohort, not a validated successful-adaptation sample. RISK:PLACEBO_DEPENDENCE, RISK:SAMPLE_SIZE_POWER."
  },
  {
   "id": "FAM:SF-CHT-063",
   "what_failed": "Attributing the BEST-vs-continue gap to a slump event as evidence of costly failure to abandon a suppressed play.",
   "why": "Apparent effect produced by a construction, selection or labelling flaw; gap is the same without a slump and with a fixed CUT-heavy ranking. RISK:BASE_RATE."
  }
 ],
 "evidence_establishes": [
  "Player absences, particularly of 'connector' players, cause significant displacement or change in a team's offensive identity/structure (FAM:SF-APPS-088, FAM:SF20).",
  "Offensive play-type mix is dynamic and shifts in response to various in-game events like halftime margins, crunch time, or after runs (FAM:SF-APPM-021).",
  "Measuring changes in offensive structure/identity is feasible, as demonstrated by metrics like D_A (FAM:SF-APPS-088).",
  "The concept of offensive reorganization following player absence is a real phenomenon."
 ],
 "evidence_does_not_establish": [
  "A robust and validated metric for 'how much the offense reorganizes' that is reliably predictive of changes in points per possession (PPP). While shifts are observed, their quantitative link to PPP change is not established.",
  "The specific causal relationship or predictive power between the *magnitude* of offensive reorganization and the *magnitude* of change in points per possession.",
  "Optimal methods for defining the baseline 'L' for offensive reorganization in the context of player absence.",
  "How to reliably control for confounding factors specific to player absence events when measuring reorganization and PPP changes."
 ],
 "own_inferences": [
  "The research question implies that player absence is the primary event triggering reorganization. This needs to be explicitly defined in the design.",
  "Defining 'offensive reorganization' quantitatively will be key, likely involving metrics of play-type distribution shifts or player role changes. The D_A metric from FAM:SF-APPS-088 seems like a good candidate for measuring 'displacement of offensive identity'.",
  "Establishing a proper baseline 'L' and pre/post periods for measuring change in both reorganization and PPP is crucial to avoid confounding and ensure interpretability."
 ],
 "uncertainties": [
  "The specific definition and robust measurement of 'how much the offense reorganizes' is not fully clear from historical evidence, although 'displacement of offensive identity' has been measured.",
  "The appropriate time window for observing 'change in points per possession' after an absence-induced reorganization is uncertain.",
  "The availability of sufficient sample size for specific player absence events, especially for 'connector' players, given previous 'small_sample' limitations (FAM:SF-APPS-088, FAM:SF20, FAM:SF-APPS-025)."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence strongly supports the premise that player absences lead to offensive reorganization, which makes the question testable in principle. However, it also highlights significant methodological risks, particularly concerning reliable measurement of reorganization, potential for artifacts, and sample size limitations, which necessitate a 'proceed_with_changes' decision to address these risks explicitly in the design. The recurring 'LABEL_ERROR' and 'MEASURE_RELIABILITY' risks for inferred labels and noisy categories (e.g., 'OTHER' play-type) are critical warnings."
 },
 "testability": {
  "p_testable": 0.6,
  "blocking_constraints": [
   {
    "code": "MEASURE_RELIABILITY",
    "text": "Quantifying 'how much the offense reorganizes' reliably can be challenging, especially if it relies on potentially noisy or inferred play-type labels (e.g., 'OTHER' category noted in FAM:SF-APPM-021, 'inferred labels' in FAM:SF-APPA-005). The D_A metric from FAM:SF-APPS-088 is a promising candidate, but its sensitivity and reliability for predicting PPP changes need scrutiny."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "Studies on player absence often face small sample sizes for specific player types or absence events (FAM:SF-APPS-088, FAM:SF20, FAM:SF-APPS-025). The stated 'n=986; n=148, mde rho; 148 spells' needs to be carefully assessed against the specific definition of 'absence' and 'reorganization events' to ensure adequate power for detecting a relationship with PPP change."
   },
   {
    "code": "CONFOUNDING",
    "text": "Player absences are not random. Other factors (e.g., opponent strength, schedule, team health, coaching strategy, concurrent injuries) could confound the relationship between reorganization and PPP change. A robust control strategy is essential."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-APPS-088",
   "FAM:SF20",
   "FAM:SF-APPM-021"
  ],
  "summary": "Previous work establishes that player absences do cause shifts in offensive identity/structure (reorganization) and that play-type mixes dynamically change within games. However, a direct predictive relationship between the *magnitude* of reorganization and the *magnitude* of change in points per possession has not been explicitly established or quantified in the retrieved literature. Methodological challenges around measurement reliability and sample size have also been identified."
 },
 "risks": [
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The metric for 'how much the offense reorganizes' must be robust and reliable. If it relies on granular play-type labels, there's a risk of noise or misclassification, as seen with 'OTHER' play-type (FAM:SF-APPM-021) or inferred defensive labels (FAM:SF-APPA-005)."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "The number of relevant player absence events leading to measurable offensive reorganization and subsequent PPP changes might be insufficient for a well-powered study, especially after controlling for confounders. Previous studies faced this (FAM:SF-APPS-088, FAM:SF20)."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player absences are often correlated with other factors that could independently affect team PPP (e.g., opponent quality, overall team health, coaching adjustments not directly related to the specific absence). These confounders need careful control."
  },
  {
   "code": "RTM_SELECTION",
   "text": "If absences are selected based on prior poor performance or if the 'L' baseline is too close to the absence event, regression to the mean could obscure or create spurious effects."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "The 'change in points per possession' must be calculated carefully from raw data to avoid introducing biases or artifacts from derived labels."
  },
  {
   "code": "BASE_RATE",
   "text": "Some types of 'reorganization' might be common regardless of player absence, or the 'change' might be an artifact of typical fluctuation, as seen with the 'BEST-vs-continue' gap (FAM:SF-CHT-063)."
  }
 ],
 "predicted_outcome": {
  "supported": 0.4,
  "rejected": 0.2,
  "untestable": 0.2,
  "artifact": 0.1,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of the magnitude of offensive reorganization (quantified by ΔD_A, the change in offensive identity displacement) on the change in points per possession (ΔPPP) following a significant player absence, after controlling for relevant confounding factors.",
  "unit": "Team-absence spell (a contiguous period of games where a specific 'connector' player is absent).",
  "sample": "NBA 2022-23 to 2025-26 regular season and playoffs. Filter for absences of 'connector' players (as defined in FAM:SF-APPS-088) lasting at least 3 consecutive games. Require sufficient 'pre-absence' (L) and 'post-absence' (A) game samples (e.g., minimum 5 games each, excluding the absence game itself). The total n=148 spells is the expected sample size.",
  "power": "The study aims to detect a moderate correlation (e.g., rho=0.3) between ΔD_A and ΔPPP with 80% power at alpha=0.05. Given n=148 spells, the MDE rho is around 0.23, suggesting that a moderate effect should be detectable. Conduct a sensitivity analysis for power based on the expected distribution of ΔD_A and ΔPPP.",
  "controls": "Match each team-absence spell with control periods: 1) The same team's performance with the player present (L) and immediately after their return. 2) Other teams' performance during similar periods without significant absences. Control for: opponent strength (e.g., ELO rating), game location, rest days, concurrent absences of other key players, and time in season. Use a difference-in-differences approach or regression with fixed effects for team and season.",
  "falsification": "1. Test if ΔD_A is significantly non-zero after connector absences, replicating FAM:SF-APPS-088. If not, the premise of reorganization is false. 2. Test if ΔD_A for non-connector absences is significantly smaller than for connector absences. 3. Test for a relationship between ΔD_A and ΔPPP in 'sham' absences (where no player was actually absent but a similar period is defined).",
  "multiplicity": "Given a single primary estimand (correlation between ΔD_A and ΔPPP), no explicit multiplicity correction is planned beyond standard hypothesis testing. Any secondary analyses (e.g., different types of reorganization metrics, different player roles) will be clearly designated as exploratory.",
  "decision_rule": "The hypothesis is supported if there is a statistically significant (p < 0.05) positive correlation between ΔD_A and ΔPPP, and the effect size is considered practically meaningful (e.g., rho > 0.15), after robust controls are applied and falsification tests do not invalidate the design. If no significant relationship is found with adequate power, the hypothesis is rejected. If power is insufficient or significant risks (e.g., MEASURE_RELIABILITY) cannot be mitigated, the result is inconclusive or untestable.",
  "data_version": "NBA 2022-23 to 2025-26 (complete data for 2022-25, partial for 2025-26 as of 2026-11-01), using derived play-type possession records and box-score summaries from NBA stats API."
 }
}

